INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6267756, 926563, 124875, '<td valign="top">I''m sorry, but I see three main problems in this photograph:<br/> <br/>1) in general, and above all, I would have liked to see his/her face while playing. What I see now it''s only a toy (and not a particularly significant one)and two hands;<br/>2) the part not in focus (i.e. his/her hair and the upper part of the skirt) aren''t good to see;<br/>3) the light is too hard.<br/> <br/>IMHO, obviously.</td>', 'I''m sorry, but I see three main problems in this photograph: 1) in general, and above all, I would have liked to see his/her face while playing. What I see now it''s only a toy (and not a particularly significant one)and two hands;2) the part not in focus (i.e. his/her hair and the upper part of the skirt) aren''t good to see;3) the light is too hard. IMHO, obviously.', '2011-01-02 19:11:15.000000', NULL, 1),
(6267775, 926571, 124875, '<td valign="top">I gave this picture a low score, because:<br/> <br/>1) the girls has a bored expression on her face (maybe this was intentional, but one doesn''t see any particular meaning in it)<br/> <br/>2) there''s no justification for the position of her head<br/> <br/>3) I don''t like the background.</td>', 'I gave this picture a low score, because: 1) the girls has a bored expression on her face (maybe this was intentional, but one doesn''t see any particular meaning in it) 2) there''s no justification for the position of her head 3) I don''t like the background.', '2011-01-02 19:18:37.000000', NULL, 1),
(6267785, 926661, 11769, '<td valign="top">Absolutely beautiful.</td>', 'Absolutely beautiful.', '2011-01-02 19:29:46.000000', NULL, 1),
(6267789, 926589, 11769, '<td valign="top">Fun effect</td>', 'Fun effect', '2011-01-02 19:31:13.000000', NULL, 1),
(6267944, 926590, 54645, '<td valign="top">sweet moment</td>', 'sweet moment', '2011-01-02 20:46:58.000000', NULL, 1),
(6267953, 926661, 76335, '<td valign="top">The girl <i>and</i> the beach?! Oh, Ben...<br/> <br/>Okay, I do like this for reasons beyond its eye candy appeal. It has a certain, subtle ominousness (would you believe that''s a word?) -- the thick clouds, the naked needy doll, the girl''s somewhat unsettled expression. They''re are all very suggestive. Of what, I don''t know. That''s where the picture ends and the viewer''s imagination picks it up. <br/> <br/>So there you are.</td>', 'The girl and the beach?! Oh, Ben... Okay, I do like this for reasons beyond its eye candy appeal. It has a certain, subtle ominousness (would you believe that''s a word?) -- the thick clouds, the naked needy doll, the girl''s somewhat unsettled expression. They''re are all very suggestive. Of what, I don''t know. That''s where the picture ends and the viewer''s imagination picks it up.  So there you are.', '2011-01-02 20:55:15.000000', NULL, 1),
(6267954, 926694, 76335, '<td valign="top">All that light! I like the feeling of concentration here.</td>', 'All that light! I like the feeling of concentration here.', '2011-01-02 20:56:06.000000', NULL, 1),
(6268073, 925989, 90474, '<td valign="top">I think including more of her head and shifting the focus from the bunny tot he kid would have made a better shot.</td>', 'I think including more of her head and shifting the focus from the bunny tot he kid would have made a better shot.', '2011-01-02 21:56:36.000000', NULL, 1),
(6268078, 926657, 90474, '<td valign="top">Changing the angle of the shot would have included more of the kid, and would have gotten rid of the flash reflection.</td>', 'Changing the angle of the shot would have included more of the kid, and would have gotten rid of the flash reflection.', '2011-01-02 21:59:12.000000', NULL, 1),
